// Arithmetic series sum of the first n natural numbers (1..=n).
// Input: n as u64, with the assumption that the exact sum is < 10_000.
// Output: exact sum as u64.

pub fn compute_arith_sum(n: u64) -> u64 {
    // Maintain:
    // - 0 <= i <= n
    // - sum == 1 + 2 + ... + i
    // - sum <= 1 + 2 + ... + n < 10_000 (by monotonicity of the series sum)
    let mut i: u64 = 0;
    let mut sum: u64 = 0;

    while i < n {
        // next term is (i + 1)
        i += 1;
        sum += i;

        // Optional safety check for the stated bound; can be removed if the
        // precondition is guaranteed by the caller/environment.
        debug_assert!(sum < 10_000);
    }

    sum
}